import numpy as np

def transform(grid):
    a=np.array(grid, dtype=int); H,W=a.shape
    # Find repeated row/column color strip, occupying at least two adjacent rows/columns.
    bar=None; seq=None
    for r in range(H):
        vals=[int(x) for x in a[r] if x]
        if not vals: continue
        cols=[c for c,x in enumerate(a[r]) if x]
        if all(np.array_equal(a[rr],a[r]) for rr in range(r,H) if False): pass
        end=r+1
        while end<H and np.array_equal(a[end],a[r]): end+=1
        if end-r>=2:
            bar={(rr,c) for rr in range(r,end) for c in cols}; seq=vals; break
    if bar is None:
        for c in range(W):
            vals=[int(x) for x in a[:,c] if x]
            if not vals: continue
            end=c+1
            while end<W and np.array_equal(a[:,end],a[:,c]): end+=1
            if end-c>=2:
                rows=[r for r,x in enumerate(a[:,c]) if x]
                bar={(r,cc) for cc in range(c,end) for r in rows}; seq=vals; break
    if bar is None: raise ValueError('stripe not found')
    # Identify connected components among remaining equal-color cells.
    seen=set(); comps=[]
    for r in range(H):
      for c in range(W):
        if not a[r,c] or (r,c) in bar or (r,c) in seen: continue
        color=int(a[r,c]); stack=[(r,c)]; seen.add((r,c)); comp=[]
        while stack:
          rr,cc=stack.pop(); comp.append((rr,cc))
          for q in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
            if 0<=q[0]<H and 0<=q[1]<W and q not in seen and q not in bar and a[q]==color:
              seen.add(q); stack.append(q)
        comps.append((color,comp))
    # Choose motif component; largest component among non-bar colored objects.
    color,comp=max(comps,key=lambda x:len(x[1]))
    r0=min(r for r,c in comp); c0=min(c for r,c in comp)
    sh=[(r-r0,c-c0) for r,c in comp]; hh=max(r for r,c in sh)+1
    # Stack all motif copies vertically with the palette sequence; preserve an existing component's slot.
    idx=seq.index(color)
    top=r0-idx*hh
    out=np.zeros_like(a)
    for i,col in enumerate(seq):
      for dr,dc in sh:
        rr=top+i*hh+dr; cc=c0+dc
        if 0<=rr<H and 0<=cc<W: out[rr,cc]=col
    return out.tolist()

