from pathlib import Path
import numpy as np

def transform(grid):
    a = np.array(grid, dtype=int)
    h, w = a.shape
    stripe = None
    for r in range(h):
        if not np.any(a[r]):
            continue
        end = r + 1
        while end < h and np.array_equal(a[end], a[r]):
            end += 1
        if end - r >= 2:
            cols = np.flatnonzero(a[r])
            stripe = ({(rr, int(c)) for rr in range(r, end) for c in cols}, [int(a[r, c]) for c in cols])
            break
    if stripe is None:
        for c in range(w):
            if not np.any(a[:, c]):
                continue
            end = c + 1
            while end < w and np.array_equal(a[:, end], a[:, c]):
                end += 1
            if end - c >= 2:
                rows = np.flatnonzero(a[:, c])
                stripe = ({(int(r), cc) for cc in range(c, end) for r in rows}, [int(a[r, c]) for r in rows])
                break
    if stripe is None:
        raise ValueError('No repeated color stripe found')
    bar, colors = stripe
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if not a[r, c] or (r, c) in bar or (r, c) in seen:
                continue
            color = int(a[r, c])
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                rr, cc = stack.pop()
                component.append((rr, cc))
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if not (dr or dc):
                            continue
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and (nr, nc) not in bar and a[nr, nc] == color:
                            seen.add((nr, nc))
                            stack.append((nr, nc))
            components.append((color, component))
    color, component = max(components, key=lambda item: len(item[1]))
    r0 = min(r for r, c in component)
    c0 = min(c for r, c in component)
    shape = [(r - r0, c - c0) for r, c in component]
    tile_h = max(dr for dr, dc in shape) + 1
    first_top = r0 - colors.index(color) * tile_h
    out = np.zeros_like(a)
    for i, new_color in enumerate(colors):
        for dr, dc in shape:
            rr, cc = first_top + i * tile_h + dr, c0 + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr, cc] = new_color
    return out.tolist()

